using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using WebOfWork.Api.Models;

namespace WebOfWork.Api.Data.EntityConfigurations;

public class GlobalSettingsConfiguration : IEntityTypeConfiguration<GlobalSettings>
{
    public void Configure(EntityTypeBuilder<GlobalSettings> builder)
    {
        builder.HasKey(x => x.Id);
        
        // Enforce Singleton: Id is never generated by the database, and we only ever use Id = 1.
        builder.Property(x => x.Id).ValueGeneratedNever();

        // Enforce decimal(18,2) constraints from the plan
        builder.Property(x => x.CommissionPercentage).HasColumnType("decimal(18,2)");
        builder.Property(x => x.MinBriefConfidence).HasColumnType("decimal(18,2)");
        builder.Property(x => x.ProposalScreeningThreshold).HasColumnType("decimal(18,2)");
        builder.Property(x => x.MatchScoreThreshold).HasColumnType("decimal(18,2)");

        // Enforce DefaultCurrency immutability
        builder.Property(x => x.DefaultCurrency)
            .IsRequired()
            .HasMaxLength(3)
            // If someone tries to modify this property on a tracked entity, EF will throw.
            .Metadata.SetAfterSaveBehavior(Microsoft.EntityFrameworkCore.Metadata.PropertySaveBehavior.Ignore);

        // Seed the singleton row
        builder.HasData(new GlobalSettings
        {
            Id = 1,
            SupportEmail = "support@webofwork.lk",
            CommissionPercentage = 10.00m,
            PayPalEmail = "payments@webofwork.lk",
            MinBriefConfidence = 0.60m,
            ProposalScreeningThreshold = 0.50m,
            MatchScoreThreshold = 0.60m,
            CreatedAt = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc),
            UpdatedAt = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc)
        });
    }
}
